class Solution {
public:
    int maxPointsInsideSquare(vector<vector<int>>& points, string s) {
        vector<int> min_sizes(26, INT_MAX);
        int second_min_size = INT_MAX;

        for (int i = 0; i < points.size(); ++i) {
            int sz = max(abs(points[i][0]), abs(points[i][1]));
            int idx = s[i] - 'a';
            if (sz < min_sizes[idx]) {
                second_min_size = min(second_min_size, min_sizes[idx]);
                min_sizes[idx] = sz;
            } else {
                second_min_size = min(second_min_size, sz);
            }
        }

        int count = 0;
        for (int sz : min_sizes) {
            if (sz < second_min_size) count++;
        }
        return count;
    }
};

class Solution {
    public int maxPointsInsideSquare(int[][] points, String s) {
        int[] minSizes = new int[26];
        Arrays.fill(minSizes, Integer.MAX_VALUE);
        int secondMinSize = Integer.MAX_VALUE;

        for (int i = 0; i < points.length; i++) {
            int sz = Math.max(Math.abs(points[i][0]), Math.abs(points[i][1]));
            int idx = s.charAt(i) - 'a';
            if (sz < minSizes[idx]) {
                secondMinSize = Math.min(secondMinSize, minSizes[idx]);
                minSizes[idx] = sz;
            } else {
                secondMinSize = Math.min(secondMinSize, sz);
            }
        }

        int count = 0;
        for (int sz : minSizes) {
            if (sz < secondMinSize) count++;
        }
        return count;
    }
}

